fn frame(t: i32) {
    host::display::clear(0x0a0e12);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::net::open("wss://relay.example.net/ticker"));
        host::display::state_set(0, 1);
    }
    let h: i32 = host::display::state_get(1);
    if h >= 0 {
        let mut got: i32 = host::net::poll(h, 4096, 220);
        while got > 0 {
            host::display::state_set(2, host::display::state_get(2) + 1);
            got = host::net::poll(h, 4096, 220);
        }
    }
    if t % 60 == 59 {
        let head: i32 = host::display::state_get(11);
        host::display::state_set(3 + head, host::display::state_get(2));
        host::display::state_set(11, (head + 1) % 8);
        host::display::state_set(12, host::display::state_get(12) + host::display::state_get(2));
        host::display::state_set(2, 0);
    }
    host::display::draw_string(110, 40, "MESSAGE RATE", 0xffffff, 2);
    host::display::draw_string(80, 90, "TOTAL", 0x888888, 1);
    host::display::draw_number(140, 88, host::display::state_get(12), 0x66ddff, 1);
    let head2: i32 = host::display::state_get(11);
    let mut i: i32 = 0;
    while i < 8 {
        let v: i32 = host::display::state_get(3 + (head2 + i) % 8);
        let mut bh: i32 = v * 12;
        if bh > 240 {
            bh = 240;
        }
        host::display::fill_rect(80 + i * 45, 400 - bh, 36, bh + 4, 0x3388cc);
        host::display::draw_number(88 + i * 45, 420, v, 0x888888, 1);
        i = i + 1;
    }
    if h < 0 {
        host::display::draw_string(80, 460, "SOCKET OFFLINE - RATE STAYS 0", 0xbb3333, 1);
    }
    host::display::present();
}
